"use client";

import { Meter as MeterPrimitive } from "@audio-ui/react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const meterVariants = cva("", {
  defaultVariants: {
    size: "default",
  },
  variants: {
    size: {
      default: "data-[orientation=vertical]:h-48 data-[orientation=horizontal]:[--meter-thickness:--spacing(3)]",
      lg: "data-[orientation=vertical]:h-64 data-[orientation=horizontal]:[--meter-thickness:--spacing(4)]",
      sm: "data-[orientation=vertical]:h-32 data-[orientation=horizontal]:[--meter-thickness:--spacing(2)]",
    },
  },
});

interface MeterProps
  extends MeterPrimitive.Root.Props,
    VariantProps<typeof meterVariants> {
  peakMarks?: "visible" | "hidden";
}

const decibels = (formattedValue: string) => `${formattedValue} dB`;

export function Meter({
  "aria-label": ariaLabel,
  className,
  size,
  peakMarks = "visible",
  ...props
}: MeterProps) {
  return (
    <MeterPrimitive.Root
      aria-label={ariaLabel}
      className={cn(
        "relative flex w-full select-none",
        "gap-1 data-[orientation=horizontal]:flex-col",
        meterVariants({ size }),
        className
      )}
      data-slot="meter"
      {...props}
    >
      <MeterPrimitive.Channels>
        {(index, channelCount) => (
          <MeterPrimitive.Channel
            aria-label={
              ariaLabel && channelCount > 1
                ? `${ariaLabel} ${index + 1}`
                : ariaLabel
            }
            className="rounded-none bg-input/70 transition-shadow duration-150 ease-out data-clipping:ring-2 data-clipping:ring-destructive relative flex-1 overflow-hidden data-[orientation=horizontal]:h-(--meter-thickness,auto) data-[orientation=horizontal]:flex-none"
            getAriaValueText={decibels}
            index={index}
            key={`meter-channel-${index}`}
          >
            <MeterPrimitive.Indicator className="bg-success data-clipping:bg-destructive absolute inset-0" />
            {peakMarks === "visible" ? (
              <MeterPrimitive.Peak className="bg-foreground absolute data-[orientation=horizontal]:top-0 data-[orientation=horizontal]:bottom-0 data-[orientation=horizontal]:w-0.5 data-[orientation=vertical]:right-0 data-[orientation=vertical]:left-0 data-[orientation=vertical]:h-0.5" />
            ) : null}
          </MeterPrimitive.Channel>
        )}
      </MeterPrimitive.Channels>
    </MeterPrimitive.Root>
  );
}
